"""OUTPUTS: contextualize already-PARTIAL CRT callbacks and shared segment marker. No promotion."""
import csv,hashlib,json,sys
from pathlib import Path
r=Path(sys.argv[1]).resolve();out=r/'crt_far_malloc_fields';out.mkdir(exist_ok=True);sha=lambda x:hashlib.sha256(x).hexdigest();proof=r/'dosbox_crt_far_malloc_runtime_v2/independent_verification.json';p=json.loads(proof.read_text(encoding='utf-8'));assert p['verified']
for x in p['files']:assert sha(Path(x['path']).read_bytes())==x['sha256']
image=r/'unpack/reproduced_image.bin';b=image.read_bytes();mp=r/'pass1_xms_move_request/noncode_intervals.csv';parts=list(csv.DictReader(mp.open(encoding='utf-8-sig')));refs=r/'crt_retry_reference_audit/summary.json';v=json.loads(refs.read_text(encoding='utf-8'))
for x in v['files']:assert sha(Path(x['path']).read_bytes())==x['sha256']
rows=[]
for name,off,n,role in [('far_malloc_retry',0x2332,4,'optional FAR16 callback; one requestWORD,nonzero AX retries/reloads'),('large_allocation_retry',0x246a,4,'optional FAR16 callback; sizeWORD/countLowWORD/countHighWORD,nonzero AX retries/reloads'),('shared_segment_marker',0x20f6,2,'unsignedWORD high-water marker; heapOS22E2 compares start_segment,large2A16 compares wrapping end_segment'),('segment_lower_bound',0x20f8,2,'unsignedWORD acceptance lower bound consumed by both allocation helpers')]:
 a=0x27710+off;e=a+n;assert all(any(int(x['start'])<=q<int(x['end_exclusive']) and x['status']=='PARTIAL' for x in parts) for q in range(a,e));rows.append(dict(field=name,start=a,end_exclusive=e,length=n,type=role,initial_bytes=b[a:e].hex(),range_sha256=sha(b[a:e]),fixed_DS_references=v['fields'][name]['fixed_references'],fixed_DS_writers=v['fields'][name]['fixed_write_references'],global_alias_writers_excluded=False,status='PARTIAL',new_bytes_typed=0))
with (out/'field_roles.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
(out/'field_roles.json').write_text(json.dumps(rows,indent=2)+'\n');s=dict(refined_already_PARTIAL_bytes=sum(x['length'] for x in rows),fields=len(rows),status_changes=0,new_deep_verified_bytes=0,runtime_tests=0,scope='Consumer-specific refinement,not newtyping or evidence ofcallbacksetters/nonuse. Earlier end-segment label applies onlyto2A16writer; sharedfield alsohasstart-segment writer.',files=[dict(path=str(q.resolve()),sha256=sha(q.read_bytes())) for q in (proof,refs,image,mp,Path(__file__))]);(out/'summary.json').write_text(json.dumps(s,indent=2)+'\n');print(json.dumps({k:v for k,v in s.items() if k!='files'},indent=2))
